"use strict";(globalThis.webpackChunkportfolio=globalThis.webpackChunkportfolio||[]).push([[81],{1988(e,t,n){n.r(t),n.d(t,{assets:()=>h,contentTitle:()=>s,default:()=>u,frontMatter:()=>r,metadata:()=>o,toc:()=>l});var o=n(6838),i=n(4848),a=n(8453);const r={slug:"writing-for-the-engineer-who-will-replace-you",title:"Writing for the Engineer Who Will Replace You",authors:"Faith Wachukwu",tags:["devops","docs"]},s=void 0,h={authorsImageUrls:[void 0]},l=[{value:"You&#39;re Not Writing for Your Team",id:"youre-not-writing-for-your-team",level:2},{value:"The &quot;Why&quot; Matters More Than the &quot;What&quot;",id:"the-why-matters-more-than-the-what",level:2},{value:"Write for the 2 AM Version of That Person",id:"write-for-the-2-am-version-of-that-person",level:2},{value:"Treat Documentation Like a Product",id:"treat-documentation-like-a-product",level:2},{value:"What I Actually Do Differently Now",id:"what-i-actually-do-differently-now",level:2},{value:"The Uncomfortable Truth",id:"the-uncomfortable-truth",level:2}];function d(e){const t={em:"em",h2:"h2",li:"li",p:"p",ul:"ul",...(0,a.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("img",{src:"/img/blog/cover-writing-engineer.jpg",alt:"An engineer working in the dark."}),"\n",(0,i.jsx)(t.p,{children:"There\u2019s a moment where you\u2019re staring at some internal documentation at 11 PM, trying to figure out why a deployment pipeline is failing, and the doc is incomplete. It just stops like the person who wrote it got pulled into a meeting and never came back."}),"\n",(0,i.jsx)(t.p,{children:"Maybe they left, or got promoted and never got back to finishing it. Well, it doesn\u2019t matter. What matters is that you\u2019re the one sitting there now, feeling betrayed by the doc.\nI\u2019ve been on both sides of that moment, staring at broken docs and leaving unfinished ones behind. But somewhere along the way, I started thinking differently about who I was actually writing for and how they would feel with an incomplete doc. And this changed everything about how I approach documentation."}),"\n",(0,i.jsx)(t.h2,{id:"youre-not-writing-for-your-team",children:"You're Not Writing for Your Team"}),"\n",(0,i.jsx)(t.p,{children:"What nobody tells you early: your colleagues might not need your docs. Yes, that's right, they might not. They were in the same Slack threads. Same meetings. They know why the authentication service talks to three different caches because they were there when someone made that questionable decision at 4 PM on a Friday.\nYour real audience is the person who is employed 18 months later, gets handed a laptop, and is told, \u201cYou own this now.\u201d\nWith no context, no slack history, and no memory of what happened previously, that shaped how the system works today. All they have is what you left behind."}),"\n",(0,i.jsx)(t.h2,{id:"the-why-matters-more-than-the-what",children:'The "Why" Matters More Than the "What"'}),"\n",(0,i.jsx)(t.p,{children:"When I started my career, I documented what things I did. Each step was written clearly, with every procedure cleanly written. Well, it became completely useless six months down the line when the step had changed completely, and I didn\u2019t update the doc.\nWhat I\u2019ve learned is that knowing the why is important. What stays beyond the steps and dashboard interfaces is the reasoning behind the decision."}),"\n",(0,i.jsxs)(t.p,{children:[(0,i.jsx)(t.em,{children:"Why did we choose Kafka over RabbitMQ?"})," ",(0,i.jsx)(t.em,{children:"Why is the timeout set to 30 seconds and not 10 seconds?"})]}),"\n",(0,i.jsx)(t.p,{children:"Knowing the context behind decisions is quite important. It\u2019s what lets the next person make good decisions instead of just following what they don\u2019t understand. I started adding more context to almost everything I write. Not like a full-blown write-up every time, sometimes it\u2019s just two sentences that can save someone the time a mistake can cost them."}),"\n",(0,i.jsx)(t.h2,{id:"write-for-the-2-am-version-of-that-person",children:"Write for the 2 AM Version of That Person"}),"\n",(0,i.jsx)(t.p,{children:"If you\u2019ve ever been on-call, you know there is a difference between reading documentation at your desk while drinking coffee versus reading it at 2 AM when everything is on fire, and your phone keeps buzzing.\nThat\u2019s a different reader. One who is not interested in whether you wrote it stylishly. They just want answers fast. They want to know:"}),"\n",(0,i.jsxs)(t.ul,{children:["\n",(0,i.jsx)(t.li,{children:"what does this service depend on?"}),"\n",(0,i.jsx)(t.li,{children:"what breaks when it goes down?"}),"\n",(0,i.jsx)(t.li,{children:"how do I restart it without making it worse?"}),"\n"]}),"\n",(0,i.jsx)(t.p,{children:"So when I am structuring anything operational, I try to keep that person in mind. I make sure I use short sentences, clear headings, and remove doubt from their minds. If there\u2019s a command they\u2019ll need to run, I include it, making sure it's easy to find and not buried deep into a paragraph section."}),"\n",(0,i.jsx)(t.h2,{id:"treat-documentation-like-a-product",children:"Treat Documentation Like a Product"}),"\n",(0,i.jsx)(t.p,{children:"One big shift in my thinking came when I stopped treating doc as a side work and started treating it as a product.\nThink about it this way: if the person replacing you can\u2019t understand the system from your documentation, then you haven\u2019t finished working on that doc."}),"\n",(0,i.jsx)(t.p,{children:"When you see documentation as a product, something that has users, a purpose, and a quality standard to follow, you start making different choices. You will think about the structure, what is important to add or what to leave out, and how to maintain it."}),"\n",(0,i.jsxs)("div",{style:{textAlign:"center"},children:[(0,i.jsx)("img",{src:"/img/blog/writingEngineer2.png",alt:"A simple flowchart showing Documentation-Users-Feedback-Improvements."}),(0,i.jsx)(t.p,{children:(0,i.jsx)(t.em,{children:"A simple workflow diagram of documentation lifecycle"})})]}),"\n",(0,i.jsx)(t.h2,{id:"what-i-actually-do-differently-now",children:"What I Actually Do Differently Now"}),"\n",(0,i.jsx)(t.p,{children:"Over time, I\u2019ve settled into a few habits that came directly from this mindset.\nI write a summary about the state of things for every system I own. I mention what works well, what\u2019s been held together with tape, and what the potential risks are."}),"\n",(0,i.jsx)(t.p,{children:"I document the things I almost forgot. Like if I had to dig through three Jira tickets and a Slack thread to figure something out, then that's a sign it needs to be written down. The fact that it was hard to find means someone will also face the same issue.\nI revisit docs when I use them. Like if I use my own runbook and something is confusing or wrong. I fix it right then and not later. Because the next person who reads it won\u2019t have context to know it\u2019s wrong, they will just trust it."}),"\n",(0,i.jsx)(t.p,{children:"And I write like a human, I use \u201cwe\u201d and \u201cyou.\u201d When something is genuinely confusing, I say, \u201cThis is confusing, but here\u2019s the deal\u201d."}),"\n",(0,i.jsx)(t.p,{children:"I don\u2019t pretend everything works perfectly when it doesn\u2019t. Being honest in documentation helps build trust, even with someone you\u2019ll never meet."}),"\n",(0,i.jsx)(t.h2,{id:"the-uncomfortable-truth",children:"The Uncomfortable Truth"}),"\n",(0,i.jsx)(t.p,{children:"A part that\u2019s hard to say out loud is: most of us will eventually leave our jobs. That\u2019s how careers work. Everything you build, every pipeline you configure, every weird shortcut you take to implement things will be inherited by someone else. And the quality of what you leave behind says something about you as a professional."}),"\n",(0,i.jsx)(t.p,{children:'I say this because I\u2019ve been on the receiving end of both brilliant and terrible handoffs. When I say brilliant, they weren\u2019t perfect systems. They were brilliant because someone took the time to write things down with the next person in mind. They left a trail that said, "I cared about whoever came after me."'})]})}function u(e={}){const{wrapper:t}={...(0,a.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(d,{...e})}):d(e)}},8453(e,t,n){n.d(t,{R:()=>r,x:()=>s});var o=n(6540);const i={},a=o.createContext(i);function r(e){const t=o.useContext(a);return o.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function s(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:r(e.components),o.createElement(a.Provider,{value:t},e.children)}},6838(e){e.exports=JSON.parse('{"permalink":"/blog/writing-for-the-engineer-who-will-replace-you","source":"@site/blog/2026-03-09-writing-for-the-engineer-who-will-replace-you.md","title":"Writing for the Engineer Who Will Replace You","description":"There\u2019s a moment where you\u2019re staring at some internal documentation at 11 PM, trying to figure out why a deployment pipeline is failing, and the doc is incomplete. It just stops like the person who wrote it got pulled into a meeting and never came back.","date":"2026-03-09T00:00:00.000Z","tags":[{"inline":true,"label":"devops","permalink":"/blog/tags/devops"},{"inline":true,"label":"docs","permalink":"/blog/tags/docs"}],"readingTime":4.95,"hasTruncateMarker":true,"authors":[{"name":"Faith Wachukwu","title":"Documentation Engineer","url":"https://faithkovi.xyz","socials":{"linkedin":"https://www.linkedin.com/in/faith-kovi/"},"imageURL":"/img/profile.jpg","key":"Faith Wachukwu","page":null}],"frontMatter":{"slug":"writing-for-the-engineer-who-will-replace-you","title":"Writing for the Engineer Who Will Replace You","authors":"Faith Wachukwu","tags":["devops","docs"]},"unlisted":false,"nextItem":{"title":"What Makes API Documentation Work?","permalink":"/blog/what-makes-api-documentation-work"}}')}}]);